'use client';
import { isInteractiveComboboxCustom, prefix } from "./utilities.js";
import { isComboboxOption } from "./Option/Option.js";
import { Children, useCallback, useMemo, useState } from "react";
//#region src/components/Combobox/useCombobox.tsx
const isOption = (option) => !!option;
function useCombobox({ children, inputValue, multiple, filter = (inputValue, option) => {
	return option.label.toLowerCase().startsWith(inputValue.toLowerCase());
}, initialValue }) {
	const filterCallback = useCallback(filter, [filter]);
	const { optionsChildren, customIds, restChildren, interactiveChildren } = useMemo(() => {
		return Children.toArray(children).reduce((acc, child) => {
			if (isComboboxOption(child)) acc.optionsChildren.push(child);
			else {
				acc.restChildren.push(child);
				if (isInteractiveComboboxCustom(child)) {
					const childElement = child;
					acc.interactiveChildren.push(childElement);
					if (!childElement.props.id) throw new Error("If ComboboxCustom is interactive, it must have an id");
					acc.customIds.push(childElement.props.id);
				}
			}
			return acc;
		}, {
			optionsChildren: [],
			customIds: [],
			restChildren: [],
			interactiveChildren: []
		});
	}, [children]);
	const options = useMemo(() => {
		const values = [];
		const allOptions = {};
		optionsChildren.map((child) => {
			const props = child.props;
			let label = props.displayValue || "";
			if (!props.displayValue) {
				let childrenLabel = "";
				Children.forEach(props.children, (child) => {
					if (typeof child === "string") childrenLabel += child;
					else throw new Error("If ComboboxOption is not a string, it must have a displayValue prop");
				});
				label = childrenLabel;
			}
			if (values.includes(props.value)) console.warn(`Combobox has multiple options with the same value: ${props.value}`);
			values.push(props.value);
			allOptions[prefix(String(props.value))] = {
				value: String(props.value),
				label,
				displayValue: props.displayValue,
				description: props.description
			};
			return null;
		});
		return allOptions;
	}, [optionsChildren]);
	const [selectedOptions, setSelectedOptions] = useState(useMemo(() => (initialValue?.map((key) => {
		return prefix(key);
	}) || []).reduce((acc, value) => {
		const option = options[value];
		if (isOption(option)) acc[value] = option;
		return acc;
	}, {}), [initialValue, options]));
	const { filteredOptions, filteredOptionsChildren } = useMemo(() => {
		const filteredOptions = [];
		return {
			filteredOptions,
			filteredOptionsChildren: Object.keys(options).map((option, index) => {
				if (!multiple && Object.keys(selectedOptions).length === 1) {
					filteredOptions.push(option);
					return optionsChildren[index];
				}
				if (multiple && selectedOptions[option]) {
					filteredOptions.push(option);
					return optionsChildren[index];
				}
				if (filterCallback(inputValue, options[option])) {
					filteredOptions.push(option);
					return optionsChildren[index];
				}
				return null;
			}).filter((child) => child)
		};
	}, [
		filterCallback,
		inputValue,
		multiple,
		options,
		optionsChildren,
		selectedOptions
	]);
	return {
		filteredOptionsChildren,
		filteredOptions,
		restChildren,
		options,
		customIds,
		selectedOptions,
		interactiveChildren,
		setSelectedOptions
	};
}
//#endregion
export { useCombobox };
